fields.InputDefinition:
{
  "goal": "Open the 'Meetings' entity grid (the Committees app's meetings) — type 'Meetings' in the LEFT sidebar 'Search record types...' box and click the exact 'Meetings' node (or, if the search is giving you trouble, navigate directly to http://localhost:4200/app/data-explorer/Data?entity=Committees:%20Meetings). Click a meeting row (for example 'Standards Committee — Q4 2015 meeting'), then click 'Open Full Record'. In the record toolbar (the row of icons at the TOP-LEFT, just above the Details card), click the Favorite control — the STAR icon (its tooltip reads 'Add Favorite' or 'Remove Favorite'; the star is gold when favorited). Click it once to TOGGLE the favorite state. Verify the state visibly changed: the star fills/empties and/or the tooltip flips between 'Add Favorite' and 'Remove Favorite', with no error. (You do not need a specific final state — toggling once is success.) Pages can take 10-30s to load — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "The Favorite (star) control in the record toolbar was clicked",
    "The favorite state visibly toggled (star fill changed and/or tooltip switched between Add/Remove Favorite)",
    "No error messages or crash pages"
  ]
}
